INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144355, 'spa', 'Beber, consumir bebida', 'Beber, consumir una bebida, específicamente vino en un banquete. Las cinco atestaciones aparecen en el relato del festín de Belsasar (Dn 5:1-23), donde el rey y su corte beben vino de los vasos saqueados del templo de Jerusalén. El español ''bebía/bebieron'' confirma el sentido de consumo. El contexto confiere al verbo una connotación de exceso sacrílego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144359, 'spa', 'Urdimbre del telar', 'La urdimbre de un telar: los hilos verticales preestablecidos por los que pasa horizontalmente la lanzadera con la trama. Se encuentra exclusivamente en la legislación levítica de pureza de Lv 13:48-59, donde el sacerdote inspecciona si una marca leprosa se ha extendido ''en la urdimbre o en la trama'' de prendas de lino o lana. Las traducciones consistentes en múltiples idiomas confirman la especificidad técnica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144362, 'spa', 'Numeral sesenta', 'El numero sesenta en arameo, presente en Esdras y Daniel. Usado para las dimensiones del templo en el decreto de Ciro: sesenta codos de alto y de ancho (Esd 6:3). La estatua de oro de Nabucodonosor media sesenta codos (Dan 3:1). Dario tenia sesenta y dos anos (Dan 5:31). Aparece en contextos imperiales de arquitectura sagrada y edades de reyes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144363, 'spa', 'Plantar, ser plantado', 'Trasplantar o plantar firmemente en el suelo, dicho de árboles y vides puestos en tierra para que arraiguen y florezcan. El participio pasivo ''plantado'' (שָׁתוּל) aparece en la entrañable imagen sapiencial del Salmo 1:3 y Jeremías 17:8: el justo ''plantado junto a corrientes de aguas''. El Salmo 92:13 extiende esta imagen a los ''plantados en la casa de Jehová''. Ezequiel emplea las formas activas para el acto soberano de Dios de trasplantar cedros y vides.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144371, 'spa', 'Orinar (el que orina)', 'Usado idiomáticamente en ''el que orina contra la pared'' como designación gráfica de cualquier varón. Las seis ocurrencias aparecen en contextos de aniquilación total de los varones de una casa: David contra Nabal (1 Sam 25:22, 34) y juicios proféticos contra dinastías israelitas (1 Re 14:10; 16:11; 21:21; 2 Re 9:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144373, 'spa', 'Calmarse, cesar', 'Aquietarse, calmarse o cesar la agitacion. El mar tempestuoso se calma cuando Jonas es arrojado al agua (Jon 1:11-12). Dios aquieta el mar en respuesta a la suplica de los marineros (Sal 107:30). La contienda cesa cuando no hay chismoso que la alimente (Prov 26:20). El verbo marca la transicion de la agitacion a la tranquilidad, tanto en las fuerzas naturales como en los conflictos humanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144376, 'spa', 'Setar-Boznai (funcionario persa)', 'El nombre propio Setar-Boznai, funcionario persa en la provincia de Trans-Éufrates. Aparece exclusivamente en Esdras 5-6, primero cuestionando la autoridad detrás de la reconstrucción del templo (Esdras 5:3, 6), y luego recibiendo la orden de Darío de apoyarla (Esdras 6:6, 13). Su etimología iraní es debatida, pero podría significar ''imperio-liberador''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144380, 'spa', 'Cámara de guardia, habitación lateral', 'Cámara de guardia, habitación lateral. Habitación pequeña y cerrada construida en el costado de una puerta monumental, usada como puesto de guardia o cámara lateral. Casi todas las ocurrencias describen las alcobas de tres cámaras en las puertas del templo visionario de Ezequiel (Ez 40:7-36), con la primera atestiguación en la ''cámara de los guardias'' (תָּא הָרָצִים) del palacio de Salomón (1 R 14:28; 2 Cr 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144392, 'spa', 'Deseo, anhelo', 'Deseo, anhelo. Deseo general o neutro, algo que se quiere sin coloración moral inherente. En Proverbios 13:12 ''el deseo cumplido es árbol de vida'', y en Salmo 10:17 Dios oye el ''deseo de los humildes''. Salmo 21:2 celebra que Dios ha concedido al rey ''el deseo de su corazón'', mostrando que este sentido puede ser plenamente positivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144393, 'spa', 'Codicia, apetito voraz', 'Codicia, apetito voraz. Ansia intensa, concupiscencia o apetito codicioso, especialmente de cosas físicas o prohibidas. Números 11:4 describe a Israel ''codiciando con codicia'' (הִתְאַוּוּ תַּאֲוָה, acusativo cognado), y el topónimo Kibrot-hataava memorializa su costo mortal. Salmo 78:29-30 y 106:14 revisitan esta glotonería del desierto. Proverbios 21:25-26 advierte que la ''codicia'' del perezoso lo mata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144396, 'spa', 'Cualidad de deseable', 'Cualidad de deseable. La cualidad de ser deseable o atractivo, funcionando casi como adjetivo. En Génesis 3:6 el árbol prohibido era ''deseable (תַּאֲוָה) para alcanzar sabiduría'', describiendo el atractivo del objeto más que la emoción del sujeto. Esta única ocurrencia marca un cambio sutil pero importante del deseo subjetivo a la cualidad objetiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144397, 'spa', 'Desear (verbo Piel)', 'Desear (verbo Piel). Uso verbal (Piel) que significa desear o elegir algo activamente. En 1 Samuel 2:16 el criado del sacerdote dice ''si el hombre desea'' (יְאַוֶּה), usando la forma verbal en lugar del sustantivo. Aunque la raíz es la misma, la morfología pasa de sustantivo a verbo activo, indicando el ejercicio deliberado de preferencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144400, 'spa', 'Anhelo profundo', 'Anhelo profundo. Anhelo o deseo hondo y personal, frecuentemente dirigido hacia Dios o que expresa devoción sincera. Isaías 26:8 habla del anhelo del alma por el nombre y el recuerdo de Dios — ''el deseo de nuestra alma es tu nombre''. Salmo 38:9 lo usa para un gemido de angustia espiritual: ''todo mi anhelo está delante de ti''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144405, 'spa', 'Gemelos, mellizos', 'Dos hijos nacidos juntos de un mismo parto. Describe a Jacob y Esau en el vientre de Rebeca (Gn 25:24) y a los hijos de Tamar y Juda (Gn 38:27). Usado poeticamente en Cantar de los Cantares para pechos pareados como cervatillos gemelos de gacela (4:5; 7:3), enfatizando simetria y belleza. Los nacimientos de gemelos en la Biblia suelen conllevar una significacion narrativa extraordinaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144407, 'spa', 'Acoplarse simétricamente', 'Estar acoplado o unido como par simétrico, dicho de los marcos del tabernáculo que debían quedar hermanados tanto abajo como arriba (Éx 26:24; 36:29). El español ''completos/parejos'' y el alemán ''schloss-sich-an'' (se unió) reflejan la precisión arquitectónica de tablas perfectamente alineadas. El origen denominativo de ''gemelo'' subraya la simetría del emparejamiento, no la mera unión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144409, 'spa', 'El fruto comestible de la higuera — los higos, típicamente en plural', 'El fruto comestible de la higuera — los higos, típicamente en plural. Usado como alimento (Nm 13:23, llevados de vuelta por los espías junto con uvas y granadas), como medicina (2 R 20:7; Is 38:21 — una torta de higos aplicada sobre la llaga de Ezequías), y en simbolismo profético (Jer 24:1-3, las dos canastas de higos buenos y malos que representan a los exiliados y a los que quedaron). La distinción entre higuera (árbol) e higos (fruto) se marca principalmente por el contexto y el número.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144410, 'spa', 'La higuera en sí (ficus carica), un árbol cultivado símbolo de paz y bendición d', 'La higuera en sí (ficus carica), un árbol cultivado símbolo de paz y bendición divina. Frecuentemente emparejada con la vid (גֶּפֶן) en la fórmula ''cada hombre bajo su vid y su higuera'' (1 R 5:5; 2 R 18:31; Mi 4:4). En Jueces 9:10-11, la higuera habla en la parábola de Jotam, rechazando la realeza por su ''dulzura y buen fruto''. La destrucción o marchitamiento de las higueras señala juicio divino (Jer 5:17; Jl 1:7, 12; Hab 3:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144435, 'spa', 'Trazar un límite', 'El sentido estándar de trazado de fronteras: un límite ''gira'' o ''se inclina'' de un punto hacia otro. Se usa repetidamente en las descripciones de la frontera Judá-Benjamín (Jos 15:9, 15:11, 18:14, 18:17), donde el límite se curva alrededor de colinas y valles. El español ''trazó'' capta la precisión cartográfica. El verbo toma complementos direccionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144436, 'spa', 'Extenderse hacia', 'Un uso estrechamente relacionado pero distinto, donde la frontera ''se extiende'' o ''sale'' hacia un destino, como en Josué 19:13 para el límite de Zabulón que alcanza Rimón y Nea. El inglés ''marked out'' y el español ''extendiéndose'' sugieren una direccionalidad más lineal que el movimiento curvo del sentido 1, aunque la acción subyacente sigue siendo la delineación de fronteras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144438, 'spa', 'Forma exterior o apariencia — El contorno visible, la silueta o el porte físico ', 'Forma exterior o apariencia — El contorno visible, la silueta o el porte físico de una persona, casi siempre en evaluaciones de belleza o de su ausencia. Se empareja con מַרְאֶה en la frase formulaica ''hermosa de forma y apariencia'' aplicada a Raquel (Gn 29:17), José (Gn 39:6) y la mujer cautiva de Deuteronomio 21:11. La inversión teológica aparece en Isaías 52:14 y 53:2, donde la forma desfigurada del Siervo desafía toda expectativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144451, 'spa', 'El arca de Noé', 'El arca de Noé: la gran embarcación construida de madera de gofer por mandato de Dios para preservar la vida durante el diluvio catastrófico. Con 26 apariciones, casi todas en Génesis 6-9, se traduce uniformemente en todos los idiomas: español el arca, francés l''arche, alemán die Arche. Su uso reiterado a lo largo del relato del diluvio (Gn 7:1, 7, 9, 17, 23; 8:1, 4, 6) subraya su centralidad como instrumento de salvación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144454, 'spa', 'La pequeña cesta de papiro en la que la madre de Moisés lo colocó para que flota', 'La pequeña cesta de papiro en la que la madre de Moisés lo colocó para que flotara entre los juncos del Nilo (Éx 2:3, 5). El francés corbeille y el alemán Körbchen distinguen esta embarcación diminuta del arca de Noé, pero el hebreo usa deliberadamente la misma palabra, conectando así los dos actos de rescate divino a través del agua y prefigurando el papel de Moisés como libertador de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144457, 'spa', 'El producto físico, cosecha o rendimiento de la tierra cultivada — lo que la tie', 'El producto físico, cosecha o rendimiento de la tierra cultivada — lo que la tierra produce. Este sentido abrumadoramente dominante rige la legislación agrícola: la תְּבוּאָה de la tierra durante el sexto año debe sustentar a Israel durante el barbecho sabático (Lv 25:20-22), y las primicias de la תְּבוּאָה pertenecen a Dios (Pr 3:9). Abarca campos de cereales, viñedos y huertos como una categoría amplia de provisión agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144462, 'spa', 'Ingresos, ganancias o beneficio económico derivado del trabajo, el comercio o la', 'Ingresos, ganancias o beneficio económico derivado del trabajo, el comercio o la inversión, más que directamente del suelo — una extensión figurada del concepto agrícola de ''rendimiento''. Con 5 apariciones concentradas en la literatura sapiencial, este sentido aparece en Proverbios 10:16 (''el ingreso del impío lleva al pecado''), Proverbios 15:6, y la sardónica observación de Eclesiastés 5:10 de que quien ama la abundancia nunca se saciará de ganancias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144466, 'spa', 'La cosecha como evento temporal u ocasión — referido al período o acto de recoge', 'La cosecha como evento temporal u ocasión — referido al período o acto de recoger los cultivos, no a los cultivos mismos. Solo 2 apariciones claras: Génesis 47:24, donde el Faraón reclama un quinto ''en las cosechas'', y Jeremías 12:13, donde el pueblo ha ''sembrado trigo pero cosechado espinos'' y está ''avergonzado de sus cosechas''. Ambos pasajes usan el término con preposiciones temporales que señalan el momento de la recolección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144487, 'spa', 'La facultad cognitiva de comprensión, perspicacia y discernimiento, ya sea human', 'La facultad cognitiva de comprensión, perspicacia y discernimiento, ya sea humana o divina. Abarca la capacidad de percibir, distinguir y juzgar rectamente. Las glosas multilingües convergen en ''entendimiento/understanding/Einsicht'', confirmando un núcleo semántico unitario. Se usa de la sabiduría dada por el Espíritu para la construcción del tabernáculo (Éx 31:3), de la nación carente de consejo (Dt 32:28), y del entendimiento divino que fundó la tierra (Pr 3:19; Jer 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144496, 'spa', 'Pericia práctica, habilidad aplicada o competencia artesanal que fluye del enten', 'Pericia práctica, habilidad aplicada o competencia artesanal que fluye del entendimiento. Se distingue de la cognición pura por el contexto más que por diferencia de glosas; el español ''conforme a su entendimiento'' todavía se superpone con el sentido 1, pero el referente se desplaza hacia la destreza manual. David pastoreando ''con la habilidad de sus manos'' (Sal 78:72) y los fabricantes de ídolos trabajando ''conforme a su entendimiento'' del oficio (Os 13:2) ejemplifican este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144508, 'spa', 'Tabor (topónimo)', 'El nombre propio Tabor, referido principalmente al monte Tabor (actual Jebel et-Tur), la icónica montaña aislada en el extremo noreste del valle de Jezreel donde Barac reunió sus fuerzas contra Sísara (Jue 4:6, 12, 14). También aparece en textos proféticos y poéticos como símbolo de grandeza (Jer 46:18; Sal 89:12) y como lugar de advertencia espiritual (Os 5:1). Además, el nombre identifica una ciudad levítica y una encina cercana a Betel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144513, 'spa', 'El mundo habitado concebido como creación establecida por Dios, usado en paralel', 'El mundo habitado concebido como creación establecida por Dios, usado en paralelismo con eretz (''tierra'') a lo largo de la poesía sálmica, profética y sapiencial. Porta un tono de grandeza cósmica ausente del prosaico eretz. Colocaciones clave incluyen תֵּבֵל וּמְלֹאָהּ (''el mundo y su plenitud'', Sal 89:12; 96:13), תֵּבֵל וְיֹשְׁבֵי בָהּ (''el mundo y sus habitantes'', Is 18:3; Nah 1:5), y la afirmación fundacional de que ''el mundo está firme, no será conmovido'' (Sal 93:1; 96:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144519, 'spa', 'Paja, tamo', 'Paja, tamo. Tallos de grano trillados o cortados usados para tres propósitos distintos en el mundo bíblico: como forraje para el ganado (Gn 24:25, 32; Jue 19:19; 1 R 5:8; Is 11:7; 65:25), como aglutinante mezclado con arcilla en la fabricación de ladrillos (Éx 5:7-18), y como metáfora profética de insignificancia o transitoriedad (Jer 23:28 contrastando paja con grano; Job 21:18 comparando al impío con paja arrastrada por el viento).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144526, 'spa', 'Rival de Omri', 'Nombre personal del rival de Omri por el trono de Israel. 1 Reyes 16:21 reporta que Israel se dividió entre seguidores de Tibni hijo de Ginat y seguidores de Omri. 1 Reyes 16:22 (dos veces) registra que el pueblo de Omri resultó más fuerte que el pueblo de Tibni, así que ''Tibni murió y Omri llegó a ser rey''. La breve noticia captura una guerra civil de seis años (implícita en la cronología) que terminó con la muerte de Tibni, ya sea en batalla o de otra forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144527, 'spa', 'Forma, semejanza, imagen', 'Forma, semejanza, imagen. Forma visible, figura o semejanza — la apariencia de algo tal como se presenta. Se usa especialmente en contextos anti-idolátricos: Deuteronomio 4:16-18 advierte contra hacer una תַּבְנִית de cualquier criatura, y Salmo 106:20 lamenta que Israel cambió la gloria de Dios por la ''imagen'' de un buey que come hierba. Ezequiel 8:3, 10 describe ''formas'' abominables vistas en visiones del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144528, 'spa', 'Patrón, plano, diseño', 'Patrón, plano, diseño. Patrón arquitectónico, plano o diseño — una especificación a seguir en la construcción. Se usa centralmente para el plano divinamente revelado del tabernáculo (Éx 25:9, 40) y del templo de Salomón (1 Cr 28:11-19), donde Dios transmite la תַּבְנִית a Moisés y a David respectivamente. También se aplica al patrón del altar copiado de Damasco (2 R 16:10) y al altar memorial de Josué 22:28.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144540, 'spa', 'Ciudad de muerte de Abimelec', 'Nombre de lugar de una ciudad cerca de Siquem donde murió Abimelec. Jueces 9:50 (apareciendo dos veces: Abimelec fue a Tebes, la sitió, la capturó) establece la escena de su caída. 2 Samuel 11:21 alude al evento: ''en Tebes'' una mujer mató a Abimelec con una piedra de molino. El nombre se volvió proverbial por reversión irónica: un aspirante a rey muerto por el arma improvisada de una mujer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144541, 'spa', 'Frágil, quebradizo', 'Participio pasivo arameo (femenino) en Daniel 2:42 que significa ''quebrado'' o ''frágil'', describiendo parte de los pies de la estatua. La composición mixta de hierro y barro produce debilidad estructural pese a la fortaleza del hierro. El término anticipa la fragmentación y destrucción definitiva del reino. Las traducciones en distintas lenguas captan esta fragilidad, concepto central en la interpretación de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144542, 'spa', 'Tiglat-pileser (rey asirio)', 'El emperador asirio Tiglat-pileser III (745-727 a.C.), quien inició las deportaciones que culminarían con la caída de Samaria. Conquistó Neftalí y Galaad, deportando sus poblaciones a Asiria (2 R 15:29), y recibió el tributo de Acaz contra la coalición siro-efraimita (2 R 16:7-10). El Cronista añade que ''angustió'' a Acaz en vez de ayudarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144548, 'spa', 'Beneficios divinos', 'El sustantivo plural con sufijo arameo en el Salmo 116:12 significa ''todos sus beneficios'', refiriéndose a los múltiples actos de bondad y liberación de Yahvé. El término se relaciona con la raíz de ''trato'' o ''retribución'', aquí en sentido positivo de bendiciones otorgadas. La pregunta retórica del salmista resalta la imposibilidad de recompensar a Dios, conduciendo a la respuesta de adoración agradecida y testimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144549, 'spa', 'Hostilidad correctiva', 'El sustantivo en estado constructo en el Salmo 39:10 significa ''hostilidad de tu mano'', describiendo la disciplina correctiva de Dios como acción adversarial. Emparentado con vocablos arameos para lucha o contienda, enfatiza el carácter conflictivo del castigo divino. La expresión personaliza el juicio: no es mero sufrimiento, sino la mano de Dios en oposición activa. Las traducciones varían entre ''golpe'' y ''contienda'', reflejando esta tensión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144554, 'spa', 'Vacío, vanidad, futilidad — vacuidad en el registro moral y teológico', 'Vacío, vanidad, futilidad — vacuidad en el registro moral y teológico: los ídolos, los falsos profetas y los planes humanos inútiles son declarados תֹּהוּ, carentes de realidad o valor. En 1 Samuel 12:21, Samuel advierte a Israel que no se desvíe tras «cosas vacías» (תֹּהוּ) que no pueden aprovechar, e Isaías 41:29 declara que los fabricantes de ídolos y sus obras son igualmente תֹּהוּ. Destaca la nada absoluta de lo que se opone a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144555, 'spa', 'Informe, caos primordial — la ausencia de forma de la tierra antes del ordenamie', 'Informe, caos primordial — la ausencia de forma de la tierra antes del ordenamiento creador de Dios, como en la fórmula fundacional תֹּהוּ וָבֹהוּ (Gn 1:2). Por extensión, el juicio profético puede reducir una tierra a este estado: Jeremías 4:23 deliberadamente evoca Génesis con la misma fórmula, e Isaías 34:11 mide a Edom con «el cordel de תֹּהוּ».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144558, 'spa', 'Vacío, nada — el vacío sobre el cual Dios actúa soberanamente', 'Vacío, nada — el vacío sobre el cual Dios actúa soberanamente: el espacio vacío de Job 26:7, donde Dios «extiende el norte sobre תֹּהוּ», e Isaías 45:18, donde Dios declara que no creó la tierra como תֹּהוּ sino que la formó para ser habitada. Evoca la vacuidad cósmica que sirve de trasfondo a la creación intencional de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144560, 'spa', 'Páramo, desolación — un desierto sin caminos e inhabitable, la desolación física', 'Páramo, desolación — un desierto sin caminos e inhabitable, la desolación física de tierras áridas o arruinadas. Deuteronomio 32:10 pone en paralelo תֹּהוּ con מִדְבָּר (desierto) para describir dónde Dios encontró a Israel, y Job 12:24 describe a los líderes vagando en un תֹּהוּ sin sendero. Subraya la vacuidad estéril, no el juicio moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144571, 'spa', 'Las profundidades oceánicas y aguas profundas — vastos cuerpos de agua que Dios ', 'Las profundidades oceánicas y aguas profundas — vastos cuerpos de agua que Dios gobierna, divide o a través de los cuales guía a su pueblo. Es el sentido más frecuente, abarcando el cruce del Mar Rojo (Éx 15:5, 8), el relato del diluvio (Gn 7:11; 8:2) y la evocación del salmista del poder de Dios sobre las aguas (Sal 77:16; 106:9). El español usa uniformemente ''abismo(s)'', el francés ''abîme'' y el alemán ''Tiefe''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144572, 'spa', 'El abismo cósmico primordial — el caos acuoso presente antes o durante la creaci', 'El abismo cósmico primordial — el caos acuoso presente antes o durante la creación, a veces personificado o con resonancia mitológica. Génesis 1:2 sitúa ''tinieblas sobre la faz del abismo'' antes de que Dios hable y haga la luz. El Salmo 104:6 rememora ese instante: ''Con el abismo lo cubriste como con vestido.'' Ezequiel 31:4, 15 recurre a esta imagen para el árbol cósmico de Asiria nutrido por el abismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144575, 'spa', 'Un abismo figurativo o metafórico — usado comparativamente para aquello que exce', 'Un abismo figurativo o metafórico — usado comparativamente para aquello que excede la comprensión humana. El Salmo 36:6 declara que los juicios de Dios son ''un gran abismo'', colocando la justicia divina más allá del entendimiento mortal. El conmovedor ''un abismo llama a otro abismo'' del Salmo 42:7 emplea la palabra como metáfora de un dolor abrumador que se precipita sobre el salmista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144581, 'spa', 'Fuentes de agua subterráneas — manantiales y pozos que brotan desde las entrañas', 'Fuentes de agua subterráneas — manantiales y pozos que brotan desde las entrañas de la tierra, frecuentemente emparejados con bendiciones del cielo arriba. Génesis 49:25 y Deuteronomio 33:13 sitúan ''el abismo que se agazapa abajo'' junto a ''los cielos de arriba'' en las bendiciones patriarcales sobre la tierra. Deuteronomio 8:7 describe la tierra prometida como poseedora de ''manantiales que brotan en valles y montes''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144588, 'spa', 'Alabanza, acto de alabar', 'Alabanza, acto de alabar. El acto o la expresión de alabar a Dios, que abarca declaraciones verbales, adoración litúrgica y devoción personal. Este sentido dominante (45 apariciones) aparece con todo tipo de sufijos pronominales —''mi alabanza'', ''tu alabanza'', ''su alabanza''— mostrando que la alabanza en hebreo es siempre relacional. Pasajes clave incluyen el llamado a ''declarar su alabanza'' (Is 42:10) y la gran asamblea de alabanza de Nehemías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144593, 'spa', 'Renombre, fama', 'Renombre, fama. Renombre, fama o cualidad de ser digno de alabanza, frecuentemente en la construcción לִתְהִלָּה (''para alabanza''). Deuteronomio 26:19 promete que Israel será puesto ''para alabanza'' sobre todas las naciones, es decir, como fuente de renombre mundial. Jeremías invierte esto: la תְּהִלָּה de Moab es acallada (48:2), Babilonia, ''la alabanza de toda la tierra'', es tomada (51:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144594, 'spa', 'Cantos de alabanza, himnos', 'Cantos de alabanza, himnos. Composiciones o himnos de alabanza específicos, que aparecen típicamente en el plural תְּהִלּוֹת. Éxodo 15:11 pregunta ''¿quién como tú, majestuoso en alabanzas?'', refiriéndose a los hechos loables de Dios relatados en cánticos. Salmo 22:3 sitúa a Dios ''entronizado sobre las alabanzas de Israel'', tratando estos himnos como el asiento mismo de la presencia divina. La forma plural señala obras literarias o litúrgicas concretas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144612, 'spa', 'Error o insensatez', 'Sustantivo disputado en Job 4:18, que posiblemente significa «error» o «insensatez» que Dios detecta incluso en sus ángeles. BDB señala una conexión con una raíz etíope que indica vagar o desviarse, sugiriendo desviación moral. Las variantes textuales y la lectura alternativa «falta de confianza» aconsejan cautela. El argumento del versículo permanece: si los ángeles son imperfectos ante Dios, cuánto más los mortales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144613, 'spa', 'Procesiones ceremoniales', 'Sustantivo plural en Nehemías 12:31 que significa «procesiones», específicamente las dos procesiones de acción de gracias organizadas para la dedicación de la muralla. La raíz sugiere caminar o movimiento, aquí formalizado como marchas ceremoniales con propósito litúrgico. Las dos procesiones moviéndose en direcciones opuestas crearon una celebración dramática y envolvente que rodeaba la ciudad, convirtiendo la adoración en un acto público y espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144614, 'spa', 'Perversidad moral', 'Perversidad o tortuosidad moral, siempre en plural (תַּהְפֻּכוֹת), que denota habla torcida, conducta desviada o carácter distorsionado. Casi todas las apariciones se concentran en Proverbios, donde describe expresiones perversas (Pr 2:12; 10:31-32; 23:33), la lengua de perversidad (Pr 10:31), la boca de perversidad (Pr 8:13), el hombre de perversidades que atiza contiendas (Pr 16:28, 30) y maquinaciones malvadas (Pr 6:14). Su única aparición fuera de Proverbios está en Deuteronomio 32:20.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144617, 'spa', 'Marca protectora visible', 'Una marca visible para identificación o protección. Job 31:35 desea ''mi marca'' (firma/sello) en una acusación escrita para que Job pudiera llevarla con orgullo—su atestación de inocencia. Ezequiel 9:4 ordena colocar ''una marca'' (tav—quizás literalmente la letra tau, con forma de X o +) en las frentes de los fieles. Ezequiel 9:6 instruye a los destructores a no tocar a nadie con ''la marca.'' Las glosas multilingües reflejan tanto el sentido de firma/sello como el de marca protectora inscrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144618, 'spa', 'Volver, regresar (Pe''al)', 'El sentido intransitivo Pe''al (Qal): volver, regresar. Las tres ocurrencias se concentran en Daniel 4, describiendo la restauracion de Nabucodonosor tras el juicio divino: su razon volvio a el (v. 34), y su brillo y esplendor real regresaron (v. 36). Los cognados siriaco תּוּב y hebreo שׁוּב comparten este significado basico de retorno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144619, 'spa', 'Restaurar, devolver (Haf''el)', 'La conjugacion Haf''el (causativa) que abarca tanto ''restaurar, devolver objetos'' como ''devolver una respuesta, replicar.'' Esdras 6:5 ordena que los utensilios de oro y plata del templo sean restituidos a su lugar. Esdras 5:5 y 5:11 describen a los ancianos judios devolviendo una respuesta al gobernador persa. Daniel 2:14 presenta a Daniel ofreciendo un consejo prudente, y en 3:16 los tres companeros dan su audaz replica al rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144624, 'spa', 'Tubal (pueblo/region)', 'El nombre propio Tubal (תּוּבַל), referido a un pueblo jafetita y su territorio en el este de Asia Menor, identificado con el Tabalu asirio (aproximadamente Capadocia). Genealogicamente, Tubal es hijo de Jafet (Gen 10:2 = 1 Cr 1:5), listado regularmente junto a Mesec, con quien forma una pareja casi formulaica en la literatura profetica. Ezequiel presenta a Tubal-Mesec como mercaderes de esclavos y bronce, guerreros caidos en el Seol y aliados de Gog.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144628, 'spa', 'Tristeza, pesar', 'Dolor emocional, tristeza o pesadumbre. El alma del salmista se deshace de pesar (Sal 119:28). Un hijo necio causa tristeza a sus padres (Prov 10:1; 17:21). Aun la risa puede encubrir un corazon afligido (Prov 14:13). La literatura sapiencial presenta la tristeza como contraparte inevitable del gozo, fruto de la necedad, las perdidas y la fragilidad de la existencia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144629, 'spa', 'Territorio septentrional', 'Territorio o pueblo del norte, probablemente en Armenia o Asia Menor, descendiente de Jafet por linea de Gomer (Gn 10:3; 1 Cr 1:6). Conocido por comerciar caballos y mulos con Tiro (Ez 27:14). Aparece entre los aliados septentrionales de Gog en la profecia escatologica (Ez 38:6). Evoca el norte remoto en la imaginacion geografica de Israel, region lejana productora de caballos de guerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144630, 'spa', 'La expresión abstracta de acción de gracias o alabanza dirigida a Dios, sentido ', 'La expresión abstracta de acción de gracias o alabanza dirigida a Dios, sentido dominante en toda la Biblia hebrea. Aparece en la adoración sálmica (Sal 26:7, ''la voz de acción de gracias''), instrucción litúrgica (Sal 95:2, emparejada con cánticos) y promesa profética (Is 51:3, acción de gracias junto al sonido de música). El francés action de grâces y el español acción de gracias captan el tono formal y declarativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144634, 'spa', 'Un sentido litúrgico especializado', 'Un sentido litúrgico especializado: coro o grupo procesional de acción de gracias. Nehemías 12:31, 38 y 40 describe dos grandes procesiones de todah caminando en direcciones opuestas sobre los muros de Jerusalén durante la ceremonia de dedicación. Aquí la palabra designa al grupo organizado de cantores y músicos, no el concepto abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144636, 'spa', 'Confesión o reconocimiento público de transgresión, estrechamente vinculado al v', 'Confesión o reconocimiento público de transgresión, estrechamente vinculado al verbo yadah en su uso confesional. En Josué 7:19, Josué exhorta a Acán a ''dar todah al SEÑOR'' confesando lo que ha hecho. Esdras 10:11 pide de manera similar todah — reconocimiento del pecado respecto a los matrimonios extranjeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144637, 'spa', 'Una ofrenda sacrificial concreta presentada en acción de gracias, parte del sist', 'Una ofrenda sacrificial concreta presentada en acción de gracias, parte del sistema de shelamim (ofrendas de paz) descrito en Levítico 7:12-15. La ofrenda de gratitud iba acompañada de tortas sin levadura y debía comerse el mismo día. En 2 Crónicas 29:31, Ezequías invita a la asamblea a traer ofrendas de acción de gracias tras la purificación del templo. Amós 4:5 la usa con aguda ironía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144644, 'spa', 'Hacer marcas o inscribir', 'Hacer marcas o inscribir una señal. 1 Samuel 21:14 (con variante Ketiv-Qere) describe a David ''garabateando'' en las puertas como parte de su acto de locura (aunque existen dificultades textuales—algunos leen ''tamborileó'' en su lugar). Ezequiel 9:4 ordena al ángel-escriba ''marcar una marca'' (acusativo cognado) en las frentes de los justos—inscribir activamente el tav protector. Las glosas multilingües (''garabateaba,'' ''marcarás'') capturan ambos usos: marcado frenético vs. inscripción deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144645, 'spa', 'Afligir o provocar', 'Perfecto Hifil (tercera persona plural) en el Salmo 78:41, que significa «afligieron» o «provocaron» al Santo de Israel. La raíz conecta con términos arameos para aflicción y arrepentimiento, aquí en uso causativo: causaron dolor a Dios mediante su incredulidad. La Septuaginta traduce «provocaron», captando la irritación. Este lenguaje antropopático retrata la violación del pacto como algo que hiere a Dios, no como mera transgresión abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144646, 'spa', 'Asombro sobrecogedor', 'Verbo arameo en perfecto (tercera persona masculina singular) en Daniel 3:24, que significa «se asombró» o «se alarmó». La reacción sobrecogida de Nabucodonosor al ver cuatro figuras en el horno impulsa la narrativa. El verbo enfatiza la sorpresa repentina y abrumadora ante lo imposible: tres hombres atados no solo vivos sino caminando libremente, acompañados de una cuarta figura divina. Su asombro abre camino al reconocimiento del Dios verdadero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144647, 'spa', 'Nombre propio', 'Nombre personal en 1 Crónicas 6:34 dentro de la genealogía de Samuel. El texto paralelo (1 Samuel 1:1) tiene «Tohú», mostrando la variación habitual en nombres propios. La importancia de este individuo radica enteramente en su conexión ancestral con Samuel, estableciendo el linaje levítico del profeta. Las versiones multilingües simplemente transliteran, como es norma con los nombres propios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144648, 'spa', 'Esperanza, expectativa', 'Esperanza o expectativa como resultado anticipado, positivo o negativo. En el Salmo 39:7, el salmista dirige su esperanza hacia Dios. Proverbios 13:12 asocia la esperanza diferida con la angustia del corazón, mientras que Proverbios 10:28 y 11:7 contrastan la expectativa justa con la esperanza que perece de los impíos. Lamentaciones 3:18 representa su uso más sombrío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144653, 'spa', 'medio, centro (espacial)', 'El sentido espacial-locativo nuclear: la región central o zona media de un lugar, tierra, cuerpo de agua, fuego u otro espacio físico. Con 335 apariciones es el uso por defecto abrumador. El firmamento divide las aguas ''en medio de'' las aguas (Gn 1:6); Abraham camina ''por en medio de'' las piezas del sacrificio (Gn 15:17); Israel pasa ''por en medio del mar'' (Éx 14:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144655, 'spa', 'entre, en la comunidad', 'El sentido interpersonal o comunitario: ''entre'' un grupo de personas, naciones o seres vivos. Se distingue del sentido espacial porque destaca la presencia social en lugar de la geometría física: Dios morando ''entre'' Israel (Éx 25:8; 29:46), dioses extranjeros ''entre'' la familia (Gn 35:2) o un extranjero viviendo ''entre'' el pueblo (Éx 12:49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144661, 'spa', 'interior, dentro de', 'El interior o lo de adentro de una entidad cerrada individual: un cuerpo, un recipiente, el ser interior de una persona, donde el significado es ''dentro de'' y no ''en el centro de.'' Un vaso de barro cuyo contenido es impuro ''dentro de él'' (Lv 11:33); los hombres de Gedeón llevan antorchas ''dentro de'' cántaros (Jue 7:16); el corazón del salmista se derrite ''dentro de mí'' (Sal 22:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144663, 'spa', 'punto medio, la mitad', 'El punto medio definido o centro absoluto de un objeto o estructura, usado con artículo o de modo absoluto para identificar una ubicación específica y no un relacional ''en medio de X.'' Abraham cortó los animales del pacto ''por la mitad'' (Gn 15:10, בַּתָּוֶךְ usado absolutamente); la ciudad se sitúa ''en el medio'' de un área medida (Nm 35:5); las ''columnas del medio'' del templo en Jue 16:29 emplean la forma articular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144702, 'spa', 'Reprensión correctiva', 'Reprensión, corrección o reproche severo. Describe días de crisis y juicio divino (2 R 19:3, Is 37:3, Os 5:9), momentos en que cae la corrección de Dios. El Salmo 149:7 habla de ejecutar castigos sobre las naciones. No es una amonestación suave, sino palabras cortantes que acompañan el juicio divino. El término combina la reprensión verbal con el castigo ejecutado, subrayando la severidad purificadora de la corrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144703, 'spa', 'Reprensión verbal, reproche o disciplina correctiva', 'Reprensión verbal, reproche o disciplina correctiva: la palabra severa pero vivificante de un padre, un sabio o de Dios que llama al oyente de vuelta al camino recto. Proverbios concentra este sentido intensamente: emparejada con musar en Pr 3:11, 12:1, 15:5, y como sello distintivo de la voz de la sabiduría en Pr 1:23, 25. Las glosas multilingües convergen en el lenguaje de corrección: español reprensión, francés reproche, alemán Zurechtweisung.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144707, 'spa', 'Argumento legal o forense, queja razonada o causa presentada en disputa formal a', 'Argumento legal o forense, queja razonada o causa presentada en disputa formal ante Dios. Job 23:4 es el paradigma: ''Llenaría mi boca de argumentos'', donde tokachath designa un razonamiento estructurado más que una corrección moral. El Salmo 38:14 lo emplea similarmente para el caso del sufriente, y Habacuc 2:1 presenta al profeta esperando oír la respuesta de Dios a su tokachath. El español argumentos y réplica captan este matiz forense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144718, 'spa', 'Topónimo simeonita', 'Nombre de lugar en 1 Crónicas 4:29, enumerado entre las ciudades simeonitas. Los estudiosos lo identifican con Eltolad de Josué, sugiriendo que תּוֹלָד es una forma abreviada. La conjunción ''y en Tolad'' lo vincula a una serie de asentamientos. La precisión geográfica en las listas genealógicas servía tanto a la memoria histórica como a posibles reclamos territoriales, algo especialmente importante para tribus como Simeón que carecían de fronteras claramente definidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144719, 'spa', 'Registro genealógico o crónica de descendientes, usado como marcador literario-e', 'Registro genealógico o crónica de descendientes, usado como marcador literario-estructural (''estas son las toledot de...'') que divide Génesis en diez secciones narrativas (Gn 2:4; 5:1; 6:9; 10:1, etc.), y como encabezados de censos o listas de clanes en Números, Éxodo y Crónicas. La evidencia interlingüística confirma el núcleo genealógico: español ''generaciones'', francés ''générations'', alemán ''Geschlechter''. La palabra abarca tanto el acto de engendrar como su registro escrito — la historia como despliegue de líneas familiares bajo la providencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144728, 'spa', 'Opresores burladores', 'Sustantivo plural con sufijo de primera persona en el Salmo 137:3 que significa ''nuestros atormentadores'' o ''los que nos hicieron lamentarnos''. BDB señala dificultad textual y posibles enmiendas. El paralelismo con ''los que nos llevaron cautivos'' sugiere opresores que añadieron burla a la derrota militar, exigiendo cantos para su diversión. El término enfatiza no solo la conquista sino la humillación, algo central a la emoción cruda del salmo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144729, 'spa', 'Gusano o escarlata', 'Puede referirse a gusanos o larvas (como en el maná echado a perder, Éx 16:20) o al tinte escarlata y carmesí (Is 1:18, Lm 4:5). El tinte se obtenía de insectos coccus ilicis triturados, lo que explica el vínculo semántico entre ''gusano'' y ''escarlata''. La promesa de Isaías contrasta pecados teñidos de carmesí que serán milagrosamente blanqueados. Una sola palabra hebrea abarca tanto la putrefacción como el lujo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144730, 'spa', 'Material tintóreo escarlata o carmesí derivado del insecto coccus ilicis, que ap', 'Material tintóreo escarlata o carmesí derivado del insecto coccus ilicis, que aparece casi exclusivamente en la construcción תּוֹלַעַת שָׁנִי junto a תְּכֵלֶת (azul) y אַרְגָּמָן (púrpura) en las instrucciones para el tabernáculo de Éxodo y Levítico. El inglés y el español coinciden en ''scarlet/gusano'', mientras el alemán usa ''Scharlach'', todos señalando el tinte más que la criatura. Predomina en 31 de las 39 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144733, 'spa', 'Un gusano o larva literal, usado para los gusanos que devoran la vid (Dt 28', 'Un gusano o larva literal, usado para los gusanos que devoran la vid (Dt 28:39; Jon 4:7), las criaturas que consumen cadáveres (Is 14:11; 66:24, emparejado con רִמָּה), y como poderosa metáfora de la insignificancia humana. El español ''gusano'' y el inglés ''worm'' convergen uniformemente aquí. El clamor del salmista ''soy gusano y no hombre'' (Sal 22:6) y el tierno ''no temas, gusano de Jacob'' de Dios (Is 41:14) transforman la imagen de repugnancia en expresión de compasión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144744, 'spa', 'Tolá (nombre propio)', 'El nombre propio Tolá, referido a un ancestro isacarita (Gn 46:13; Nm 26:23; 1 Cr 7:1-2) y a un juez de Israel de la misma tribu que gobernó veintitrés años (Jue 10:1). Las versiones en español (''Tolá''), francés (''Thola/Tola'') y alemán (''Tola'') lo transliteran consistentemente. El nombre podría conectarse con tolaat (''gusano/escarlata''), pero funciona exclusivamente como identificador personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144746, 'spa', 'Gentilicio clan Tola', 'Adjetivo gentilicio con artículo definido en Números 26:23, que designa al clan descendiente de Tola de Isacar. Usado colectivamente (el tolaíta = todos los tolaítas), funciona como designación de clan en el censo del desierto. Las versiones multilingües preservan la forma gentilicia, reconociéndolo como un identificador étnico-familiar esencial para la organización tribal de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144747, 'spa', 'abominación, cosa detestable', 'La forma singular (55 apariciones) que identifica un acto, práctica u objeto específico como moral o ritualmente detestable. Gn 43:32 la aplica al tabú cultural egipcio de comer con hebreos, Éx 8:26 a prácticas sacrificiales repugnantes para los egipcios, y las leyes de Deuteronomio marcan ofensas individuales como ''abominación ante el SEÑOR'' (Dt 7:25; 22:5; 23:18). El singular lleva una fuerza señalada y precisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144749, 'spa', 'abominaciones, prácticas detestables', 'La forma plural (63 apariciones) que cataloga múltiples actos detestables o prácticas idolátricas de manera colectiva, usada extensamente en las requisitorias proféticas. Solo Ezequiel concentra una gran proporción, enumerando las ''abominaciones'' acumuladas de Jerusalén y de las naciones. Lv 18:26-30 enmarca toda la colección de prohibiciones sexuales bajo este plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144783, 'spa', 'Alturas imponentes', 'Eminencia, alturas elevadas o cimas imponentes. Los oráculos de Balaam lo emplean para la fuerza de Israel, comparada con los cuernos elevados del búfalo (Nm 23:22; 24:8). El Salmo 95:4 habla de las cumbres de los montes como posesión de Dios. Job 22:25 podría referirse a montones de plata o usar ''alturas'' como metáfora del Todopoderoso. El término subraya la dimensión vertical: altura, fortaleza y grandeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144784, 'spa', 'El punto de salida o extremo terminal de un límite territorial, usado extensamen', 'El punto de salida o extremo terminal de un límite territorial, usado extensamente en las descripciones de reparto de tierras. Números 34:4-12 traza las fronteras de Canaán por sus totsaot, y Josué 15-19 cartografía la heredad de cada tribu de la misma manera. La forma plural y las cadenas constructas (''sus salidas'') marcan los puntos geográficos finales. El español sus salidas y el francés ses sorties transmiten el sentido de donde una frontera termina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144789, 'spa', 'Escape o liberación de la muerte, usado de manera única en el Salmo 68', 'Escape o liberación de la muerte, usado de manera única en el Salmo 68:20 (hebreo v. 21): ''De Dios el Señor son las salidas de la muerte.'' Aquí la metáfora fronteriza se transpone al ámbito de la mortalidad: Dios controla los pasajes de salida del dominio de la muerte. El español salidas y el inglés escapes captan este giro teológico de la geografía a la salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144791, 'spa', 'Fuente, manantial u origen, usado metafóricamente en Proverbios 4', 'Fuente, manantial u origen, usado metafóricamente en Proverbios 4:23: ''Guarda tu corazón, porque de él manan las totsaot de la vida.'' La dirección se invierte: no donde algo termina sino donde se origina. El corazón es la fuente de la cual fluyen las corrientes de la vida. Algunos eruditos enmiendan a motsa''ot, pero el texto masorético permanece como una poderosa imagen de origen interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144794, 'spa', 'Espiar o reconocer un territorio con fines militares o de asentamiento', 'Espiar o reconocer un territorio con fines militares o de asentamiento. Este es el sentido dominante, con dieciséis apariciones en el Pentateuco y Jueces. Los doce espías recorrieron Canaán desde el desierto de Zin hasta Rejob (Nm 13:21), y los danitas enviaron cinco hombres a espiar la región montañosa (Jue 18:2). El español espiar y el francés espionner conservan el matiz de recopilación de inteligencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144795, 'spa', 'Escudriñar o investigar mediante indagación intelectual', 'Escudriñar o investigar mediante indagación intelectual. Qohélet emplea este verbo cuatro veces para sus exploraciones filosóficas: ''Apliqué mi corazón a escudriñar con sabiduría todo lo que se hace debajo del cielo'' (Ec 1:13). El paso de la exploración geográfica a la mental es natural: el mismo sondeo deliberado y exhaustivo se dirige ahora a la sabiduría y la necedad. El alemán erforschen y el español escudriñar captan esta extensión intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144796, 'spa', 'En la conjugación Hifil, tener ventaja sobre otro o sobresalir en valor', 'En la conjugación Hifil, tener ventaja sobre otro o sobresalir en valor. Este sentido raro aparece en Proverbios 12:26, donde el justo aventaja o guía a su prójimo. La noción de superioridad puede derivar de la idea de ir más allá o explorar más lejos que otro. La evidencia multilingüe es escasa aquí, y la mayoría de las traducciones recurren a la paráfrasis, lo que sugiere una extensión especializada del sentido exploratorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144799, 'spa', 'Como sustantivo participial (hattorim), designa a comerciantes o mercaderes', 'Como sustantivo participial (hattorim), designa a comerciantes o mercaderes: aquellos que ''recorren'' para comerciar. Aparece en el recuento de los ingresos de Salomón junto a las ganancias de ''los comerciantes'' (1 R 10:15; 2 Cr 9:14). El camino semántico de ''quien anda explorando'' a ''mercader itinerante'' refleja la realidad antigua de las caravanas comerciales que exploraban rutas y mercados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144811, 'spa', 'Trenza o turno', 'Abarca tanto el trenzado ornamental (especialmente en la imaginería de belleza del Cantar de los Cantares) como las ocasiones señaladas (en el protocolo real de Ester). El español ''pendientes'' y el inglés ''ornaments'' apoyan el sentido decorativo, mientras que el francés ''tour'' capta el significado temporal y secuencial. La idea común parece ser ''disposición en orden'': ya sea de hilos trenzados o de turnos sucesivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144812, 'spa', 'Manera o costumbre', 'El sustantivo en estado constructo en 1 Crónicas 17:17 aparece en una frase difícil, a menudo traducida como ''manera de hombre'', aunque su significado es disputado. BDB señala corrupción textual y diversas enmiendas propuestas. El texto paralelo ofrece ''torá del hombre'', también problemático. El sentido general de David es claro —asombro ante la condescendencia de Dios— pero la expresión precisa sigue siendo elusiva, recordándonos que algunos textos antiguos resisten una interpretación definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144813, 'spa', 'tórtola — La tórtola (Streptopelia turtur), llamada onomatopéyicamente por su ar', 'tórtola — La tórtola (Streptopelia turtur), llamada onomatopéyicamente por su arrullo. Aparece principalmente en la legislación sacerdotal como ofrenda sacrificial aceptable, típicamente en pareja con palominos (Lv 1:14, 5:7, 12:6, 15:14; Nm 6:10). Fuera del culto, aparece como símbolo de retorno estacional (Jer 8:7, Cnt 2:12) y de la vulnerabilidad de Israel bajo el cuidado divino (Sal 74:19). Las traducciones en diversas lenguas son notablemente uniformes: español ''tórtola'', francés ''tourterelle'', alemán ''Turteltaube''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144820, 'spa', 'Toros, ganado (arameo)', 'Sustantivo plural arameo que significa toros o bueyes, utilizado para ganado bovino en dos contextos: como animales sacrificiales proporcionados para el culto del Templo (Esd 6:9, 17; 7:17, enumerados junto a carneros y corderos en los decretos de Dario y Artajerjes), y como bestias del campo cuya vegetacion consumio Nabucodonosor durante su locura impuesta divinamente (Dan 4:25, 32, 33; 5:21). Cognado del hebreo שׁוֹר y del siriaco תַּוְרָא.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144823, 'spa', 'Ley / Torá (instrucción divina)', 'La Ley mosaica, la Torá de YHWH: el sentido dominante con 203 apariciones. Abarca la Torá como cuerpo integral de instrucción divina del pacto, ya se especifique como ''la Torá de Moisés'' (Jos 8:31), ''la Torá del SEÑOR'' (Sal 19:7) o simplemente ''la Torá'' con artículo. Incluye el Pentateuco como documento escrito, las estipulaciones del pacto y todo el corpus legislativo-narrativo mosaico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144844, 'spa', 'instrucción, enseñanza (humana)', 'Instrucción o enseñanza humana o profética: 5 apariciones donde תּוֹרָה conserva su sentido etimológico de ''dirección, guía'' sin referencia directa al código mosaico. La enseñanza de una madre (Pr 1:8; 6:20), la instrucción de un padre (Pr 3:1; 4:2) y la ley de bondad en los labios de la mujer virtuosa (Pr 31:26). El alemán Weisung (''directriz'') capta este sentido pedagógico no legislativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144846, 'spa', 'leyes, regulaciones (plural)', 'Leyes, regulaciones o estatutos rituales específicos: el plural תּוֹרֹת, con 14 apariciones. Se trata de prescripciones individuales contables y no de la Torá como totalidad unificada: ''la ley del holocausto'' (Lv 6:9), ''la ley de la ofrenda vegetal'' (Lv 6:14), ''la ley de la ofrenda por el pecado'' (Lv 6:25). Dios dio a Israel ''leyes e instrucciones'' (Gn 26:5; Éx 16:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144890, 'spa', 'Instrucción divina', 'La forma constructa ''torá de'' en 2 Samuel 7:19 aparece en una frase textualmente difícil. Normalmente תּוֹרָה significa instrucción o ley: enseñanza divina que dirige la vida. Puede denotar sabiduría paterna (Proverbios), instrucción sacerdotal o el pacto mosaico. Aquí la frase ''torá del hombre'' es oscura, posiblemente corrupta. En todo caso, la Torá a lo largo de las Escrituras representa la autorrevelación bondadosa de Dios y la guía para su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144891, 'spa', 'extranjero residente, forastero establecido — Extranjero residente o forastero e', 'extranjero residente, forastero establecido — Extranjero residente o forastero establecido que habita en medio de la comunidad del pacto con un estatus reconocido aunque limitado. Este es el uso mayoritario, concentrado en Levítico 25 y Números 35, donde el toshav tiene derechos definidos: vivir junto a los israelitas, beneficiarse de las provisiones del descanso sabático (Lv 25:6), acceder a las ciudades de refugio (Nm 35:15), y ser adquirido o comprado como siervo (Lv 25:35-47).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144896, 'spa', 'peregrino, morador temporal — Peregrino o morador temporal cuya estancia es tran', 'peregrino, morador temporal — Peregrino o morador temporal cuya estancia es transitoria y cuya identidad está marcada por la impermanencia y la condición de foráneo. Éxodo 12:45 empareja toshav con sakir (jornalero), excluyendo a ambos de la cena pascual, una exclusión cultual que resalta su condición de extraño. En 1 Crónicas 29:15, David declara ''somos forasteros y peregrinos delante de ti'', y el Salmo 39:12 repite la misma confesión existencial de transitoriedad ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144902, 'spa', 'De Tisbé de Galaad', 'Frase preposicional en 1 Reyes 17:1 que probablemente significa «de Tisbé en Galaad», identificando la ciudad natal de Elías. BDB y los comentaristas modernos prefieren enmendar el texto masorético «moradores» al topónimo «Tisbé» basándose en la Septuaginta y el contexto. Esto establece a Elías como un profeta transjordano, un forastero que confronta al poder real de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144903, 'spa', 'Sabiduría sólida, discernimiento', 'Sabiduría sólida, discernimiento práctico o profunda capacidad de recursos: la facultad de juicio y consejo eficaz. Se aplica a la sabiduría de Dios en Isaías 28:29 y Job 12:16, a la Sabiduría personificada en Proverbios 8:14, y como algo que el discípulo debe guardar (Pr 3:21) o que la necedad pone en riesgo (Pr 18:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144904, 'spa', 'Éxito, liberación', 'El resultado práctico de la sabiduría sólida: éxito, ayuda eficaz o liberación concreta. En Job 5:12, Dios frustra los planes de los astutos para que no logren תּוּשִׁיָּה — ningún ''éxito''. Job 6:13 pregunta si la ayuda eficaz ha sido arrebatada de él. Job 12:16 la empareja con עֹז (''fuerza''), enfatizando eficacia más que intelecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144913, 'spa', 'Garrote o maza', 'Sustantivo en Job 41:29 que designa un garrote o maza, un arma contundente. En la descripción de la invulnerabilidad de Leviatán, los garrotes son «como paja» para la bestia. El término forma paralelo con «jabalina», abarcando armas de impacto. La imagen subraya la incapacidad humana de dominar a la criatura, parte de la lección de Job sobre los límites del poder humano ante el misterio de la creación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144914, 'spa', 'Podar sarmientos', 'Única aparición en Isaías 18:5, donde este verbo designa la remoción de zarcillos de la vid, una acción de poda que prepara la planta. La evidencia interlingüística y el dominio agrícola confirman que es vocabulario técnico de viticultura, empleado metafóricamente para el juicio divino que elimina lo infructuoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144915, 'spa', 'Fornicación, prostitución o promiscuidad, usada tanto para la infidelidad sexual', 'Fornicación, prostitución o promiscuidad, usada tanto para la infidelidad sexual literal como, de manera más prominente, como metáfora profética de la infidelidad espiritual de Israel mediante la idolatría y las alianzas políticas prohibidas. Todas las apariciones se limitan a Ezequiel 16 y 23, las dos grandes alegorías de Jerusalén y Samaria como esposas infieles. El sustantivo siempre aparece con sufijos posesivos (''tus fornicaciones'', ''sus fornicaciones''), haciendo la acusación intensamente personal. El alemán Hurerei y el francés fornication preservan la severidad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144926, 'spa', 'Guia, consejo, estrategia', 'Consejo sabio, direccion estrategica o guia prudente. La palabra evoca la metafora original de tirar cuerdas para dirigir un barco, y en sus siete ocurrencias describe consistentemente el arte de la planificacion prudente. En Proverbios se empareja con ''multitud de consejeros'' (11:14; 24:6) y ''consejo'' (20:18), enmarcando el liderazgo como una habilidad de navegacion. Job 37:12 la aplica a la direccion soberana de Dios sobre los fenomenos atmosfericos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144932, 'spa', 'Antepasado levítico', 'Antepasado levítico del profeta Samuel, este nombre aparece en listas genealógicas que vinculan a Samuel con la tribu de Leví. El pasaje paralelo en 1 Samuel 1:1 emplea una vocalización ligeramente distinta, un patrón habitual en las genealogías bíblicas donde las tradiciones escribales conservan variantes ortográficas del mismo individuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144933, 'spa', 'Debajo de', 'Marca relaciones espaciales de subordinación o cobertura. En las visiones de Daniel aparece con gran alcance cósmico: ''debajo de todos los cielos'' (7:27) y en la imagen del árbol de Nabucodonosor que cobija a las bestias ''debajo de él'' (4:12, 21). La traducción uniforme en todas las lenguas (''debajo de'', ''under'') confirma que se trata de una preposición locativa directa sin ambigüedad semántica significativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144934, 'spa', 'Gentilicio de clan', 'Designación gentilicia de Joseb-basebet, jefe de los treinta valientes de David. El texto paralelo en 1 Crónicas lee «Jasobeam, hacmonita», lo que sugiere corrupción textual o variación dialectal. Tales marcadores étnicos eran esenciales para distinguir a guerreros con nombres similares en los registros antiguos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144935, 'spa', 'El punto inicial, primera fase o comienzo de un evento, periodo o proceso', 'El punto inicial, primera fase o comienzo de un evento, periodo o proceso. Se usa tanto en forma absoluta con artículo (battekhillah, ''al principio'', Gn 13:3; 43:18) como en cadenas constructas (tekhillat khokmah, ''el principio de la sabiduría'', Pr 9:10; tekhillat dibber YHWH, ''cuando el SEÑOR habló por primera vez'', Os 1:2). Todas las glosas multilingües convergen en ''comienzo/principio'', confirmando un sentido único y bien definido a lo largo de sus 23 atestaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144946, 'spa', 'Enfermedades, dolencias graves', 'Enfermedades o dolencias crónicas, aflicciones severas vistas bajo el lente teológico de juicio pactual o sanidad divina. En Dt 29:22, las enfermedades señalan maldición; en 2 Cr 21:19, las dolencias incurables de Joram son castigo divino. Jeremías describe ''enfermedades de hambruna'' como juicio total (Jer 14:18; 16:4). El Salmo 103:3 transforma el término en alabanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144949, 'spa', 'Lugar de campamento', 'En la frase ambigua de 2 Reyes 6:8, designaría el lugar o el acto de establecer un campamento, en consonancia con el conocimiento profético de Eliseo sobre las posiciones militares arameas. Sin embargo, la forma inusual ha llevado a la mayoría de los estudiosos a sospechar una corrupción textual, y la lectura siríaca de «esconderse» ofrece una alternativa más sencilla que igualmente encaja en el contexto de inteligencia militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144950, 'spa', 'Ruego humilde y ferviente dirigido a Dios o a un superior humano, buscando favor', 'Ruego humilde y ferviente dirigido a Dios o a un superior humano, buscando favor compasivo o alivio. El sentido dominante en 23 apariciones, frecuentemente emparejado con tefillah (''oración'') en la dedicación de Salomón (1 R 8:28, 30, 38, 45, 49, 52; 2 Cr 6:19, 29, 35, 39). También en la frase urgente de Jeremías ''caiga mi súplica delante de ti'' (Jer 37:20; 42:2). El español ''súplica'' y el francés ''supplication'' reflejan fielmente este sentido de petición humilde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144956, 'spa', 'La cualidad de gracia, favor o misericordia en sí misma — la disposición que se ', 'La cualidad de gracia, favor o misericordia en sí misma — la disposición que se busca y no el acto de buscarla. En Jos 11:20, Dios endureció el corazón de los cananeos para que no se les mostrara ''clemencia'' alguna. En Esd 9:8, el remanente reconoce un breve momento de ''gracia de parte del SEÑOR''. El francés ''grâce'' y el alemán ''Gnade'' confirman el cambio de ''súplica'' a ''favor concedido''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144966, 'spa', 'Nombre propio judahita', 'Descendiente en la línea de Judá, preservado en el amplio marco genealógico de Crónicas. La posible conexión del nombre con «súplica» (תְּחִנָּה) se alinea con la práctica de dar a los hijos nombres que reflejaran la oración o el favor divino, un patrón recurrente en toda la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144967, 'spa', 'Súplicas, ruegos de misericordia — peticiones fervientes y reiteradas de miseric', 'Súplicas, ruegos de misericordia — peticiones fervientes y reiteradas de misericordia y gracia, dirigidas de manera abrumadora a Dios. La forma exclusivamente plural intensifica la urgencia de la apelación. Se empareja con תְּפִלָּה en contextos de oración formal (Sal 143:1; Dn 9:3, 17) y con el llanto en el dolor profético (Jer 3:21; 31:9). Los Salmos atesoran especialmente la frase קוֹל תַּחֲנוּנִים, «la voz de mis súplicas» (Sal 28:2, 6; 86:6; 130:2). Proverbios 18:23 ofrece su único uso entre personas: el pobre habla תַּחֲנוּנִים.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144977, 'spa', 'Clan efraimita', 'Designación colectiva para los miembros del clan de Taján dentro de Efraín, utilizada en el censo del desierto para enumerar la subdivisión tribal. Este tipo de gentilicio patronímico, marcado con el artículo, funciona como nombre de familia que identifica a todos los descendientes del ancestro epónimo Taján mencionado antes en la genealogía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144978, 'spa', 'Tajpanjés (ciudad egipcia)', 'El nombre propio Tajpanjés (תַּחְפַּנְחֵס), también escrito תְּחַפְנְחֵס en Ez 30:18, designa una fortaleza fronteriza egipcia en el delta nororiental, correspondiente a la Dafne griega. La ciudad servía como guarnición militar y punto de entrada a Egipto. Jeremías 2:16 la empareja con Menfis (Nof) como representante del poder egipcio. Tras la caída de Jerusalén, los judíos que huyeron se establecieron allí contra la voluntad profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144984, 'spa', 'Reina egipcia', 'Nombre propio de una reina egipcia en la era de Salomón. 1 Reyes 11:19 identifica a Tajpenes como la reina egipcia cuya hermana el Faraón dio a Hadad en matrimonio. 1 Reyes 11:20 (aparece dos veces) relata que esta hermana dio a luz a Genubat, a quien ''Tajpenes destetó'' y crió en el palacio del Faraón entre los niños reales. El involucramiento personal de la reina en criar a su sobrino muestra intimidad familiar e importancia política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144987, 'spa', 'Nombre propio benjaminita', 'Benjaminita del linaje de Saúl, este nombre aparece en los registros genealógicos de Crónicas con ligera variación respecto al pasaje paralelo. La preservación de tales nombres demuestra el afán de Crónicas por mantener los registros familiares incluso de figuras menores, asegurando la documentación de la línea real a lo largo del período del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144988, 'spa', 'animal del cuero tachash (marsopa/dugongo/foca) — El tachash como criatura vivie', 'animal del cuero tachash (marsopa/dugongo/foca) — El tachash como criatura viviente, un mamífero marino (dugongo, marsopa o foca) cuya piel se cosechaba para las cubiertas del tabernáculo. Casi las catorce apariciones corresponden a este sentido. El plural ''orot hat-techashim'' (Éx 25:5; 35:7) y el constructo ''or tachash'' (Nm 4:6-14) señalan consistentemente al animal como fuente de una piel específica. La evidencia interlingüística es reveladora: el inglés usa ''porpoise'' o ''sea cow'', el español ''tejón'' y el francés ''tahash''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144992, 'spa', 'cuero de tachash / piel de tachash (material) — Desplazamiento metonímico del an', 'cuero de tachash / piel de tachash (material) — Desplazamiento metonímico del animal al material: el cuero de tachash como piel procesada. En Ezequiel 16:10, la palabra designa el producto terminado y no la criatura viva, describiendo sandalias de cuero fino que Dios dio a Jerusalén. El inglés lo traduce simplemente como ''leather'', mientras que el español usa ''piel de tejones'' y el francés conserva el préstamo ''tahash'', mostrando cómo los traductores manejan el cambio del animal al producto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144993, 'spa', 'Sobrino de Abraham', 'Hijo del hermano de Abraham, Nacor, incluido entre los descendientes que pueblan el norte de Mesopotamia y Siria. La posible conexión geográfica con una localidad siria refleja el patrón de Génesis de insertar topónimos y orígenes étnicos dentro de las genealogías, creando un mapa familiar del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144994, 'spa', 'debajo de, bajo (espacial)', 'Ubicación física debajo o por debajo de algo: el uso más literal y frecuente. Incluye ''debajo de todo árbol frondoso'' (Dt 12:2), ''debajo de todo el cielo'' (Dt 2:25) y combinaciones con מִן (מִתַּחַת, ''de debajo de''). Las glosas en diversas lenguas convergen en preposiciones espaciales: ''sous,'' ''unter,'' ''bajo,'' confirmando el significado posicional concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144995, 'spa', 'en lugar de, en vez de', 'Sustitución, sucesión o intercambio: una entidad que ocupa el rol o la posición de otra. Central en las fórmulas de sucesión dinástica (''reinó en su lugar,'' 1 R 15:8) y en la teología de la ofrenda sustitutiva (Gn 22:13, el carnero ''en lugar de'' Isaac). También cubre ''a cambio de'' en contextos comerciales y de retribución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145009, 'spa', 'porque, por cuanto (causal)', 'Conjunción causal, casi siempre en la frase fija תַּחַת אֲשֶׁר (''porque, por cuanto''). Este sentido raro pero importante aparece en la retórica deuteronómica: ''por cuanto no serviste al SEÑOR tu Dios'' (Dt 28:47). Solo 13 apariciones, pero teológicamente significativas en contextos de maldiciones del pacto (Nm 25:13; Dt 21:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145065, 'spa', 'Debajo de, bajo', 'En Daniel 4:14, describe lo que se encuentra espacialmente ''debajo'' del gran árbol en el sueño de Nabucodonosor: las bestias, las aves y las naciones cobijadas bajo su dominio. La preposición transmite tanto ubicación física como sujeción metafórica, pues el árbol representa el poder imperial que extiende su protección y control sobre quienes están ''debajo'' de él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145066, 'spa', 'Tajat (nombre personal)', 'Tajat como nombre personal portado por al menos dos individuos: un levita descendiente de Coat en la organización cultual de David (1 Cr 6:24, 37) y un efraimita en la genealogía de la tribu de Josué (1 Cr 7:20). El francés ''sous'' y el alemán ''unter'' traducen el significado etimológico ''debajo'', aunque funciona como identificador propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145068, 'spa', 'Tajat (estación del desierto)', 'Tajat como estación geográfica en el itinerario del desierto de Números 33:26-27, ubicada entre Makelot y Téraj. El uso preposicional ''de Tajat'' y ''en Tajat'' lo marca como campamento en el viaje de cuarenta años. Las formas españolas conservan el topónimo, mientras que la ubicación permanece sin identificar arqueológicamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145070, 'spa', 'inferior, el más bajo — Que ocupa la posición espacial inferior o más baja, ya s', 'inferior, el más bajo — Que ocupa la posición espacial inferior o más baja, ya sea en arquitectura o geografía. Describe el nivel más bajo de las cámaras laterales del templo (1 R 6:6, 8; Ez 41:7; 42:5-6), el pavimento y la puerta inferiores del atrio exterior del templo (Ez 40:18-19), el reborde inferior del altar (Ez 43:14) y la piscina inferior de Jerusalén (Is 22:9). Aparece de manera prominente en el topónimo Bet-horón de abajo (Jos 16:3; 18:13; 1 Cr 7:24; 2 Cr 8:5), diferenciando la ciudad baja de la alta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145077, 'spa', 'Partes más bajas, profundidades (Seol/inframundo) — las regiones más profundas o', 'Partes más bajas, profundidades (Seol/inframundo) — las regiones más profundas o del inframundo, un uso sustantivado que se refiere al Seol, el mundo subterráneo bajo la tierra de los vivos. Moisés advierte que la ira de Dios arde «hasta lo profundo del Seol» (Dt 32:22), el salmista agradece a Dios por rescatarlo «de las profundidades del Seol» (Sal 86:13), y Ezequiel consigna a naciones orgullosas a «las profundidades de la tierra» (Ez 26:20; 31:14-18; 32:18-24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145078, 'spa', 'Inferior (adjetivo comparativo) — que ocupa una posición relativamente más baja ', 'Inferior (adjetivo comparativo) — que ocupa una posición relativamente más baja respecto a otra cosa, usado atributivamente en contextos arquitectónicos, geográficos o anatómicos. Cuatro ocurrencias incluyen los «pisos inferiores» del arca de Noé (Gn 6:16), los «manantiales inferiores» dados a Acsa por Caleb (Jos 15:19; Jue 1:15), y la «piedra de molino inferior» que describe la dureza impenetrable de Leviatán (Job 41:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145080, 'spa', 'Fondo, base (de un accidente geográfico) — uso locativo con preposición que indi', 'Fondo, base (de un accidente geográfico) — uso locativo con preposición que indica posición al pie o en el punto más bajo de un hito. Una ocurrencia clara en la teofanía del Sinaí: «Moisés sacó al pueblo del campamento para encontrarse con Dios, y se situaron al pie del monte» (Éx 19:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145091, 'spa', 'Del medio, central', 'Adjetivo posicional que significa ''del medio'' o ''central'', señalando el elemento intermedio en una serie tripartita. Designa el piso central de las cámaras del Templo (1 R 6:6, 8) y la barra central del tabernáculo (Ex 26:28; 36:33). Se extiende temporalmente a la ''vigilia de en medio'' (Jue 7:19) y al nivel medio del templo visionario de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145097, 'spa', 'Territorio árabe ismealita', 'Nombre propio que designa el territorio árabe centrado en el oasis de Teyma y el clan ismaelita asociado. Aparece en genealogías (Gn 25:15; 1 Cr 1:30), oráculos proféticos contra pueblos árabes (Is 21:14; Jer 25:23) y poesía sapiencial describiendo caravanas comerciales (Job 6:19). Las traducciones transliteran uniformemente el nombre como ''Tema''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145098, 'spa', 'El punto cardinal sur o la región meridional, usado como sustantivo locativo o d', 'El punto cardinal sur o la región meridional, usado como sustantivo locativo o direccional. Éxodo 26:18 y 36:23 lo emplean para el lado sur del Tabernáculo; Isaías 43:6 lo empareja con ''norte'' para la orientación geográfica. La forma con he-locale teymanah (''hacia el sur'') representa la mayoría de las apariciones. El español ''al sur'', el francés ''de sud'' y el alemán ''Süden'' confirman la lectura direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145101, 'spa', 'El viento del sur como fenómeno meteorológico', 'El viento del sur como fenómeno meteorológico. El Salmo 78:26 describe a Dios haciendo surgir el viento del sur con su poder, y Cantar de los Cantares 4:16 lo invoca poéticamente: ''¡Despierta, viento del sur!'' El español ''viento del sur'' y el inglés ''south wind'' en estos dos pasajes distinguen este sentido del meramente direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145109, 'spa', 'Temán (topónimo)', 'Región o ciudad principal de Edom, nombrada por Temán, nieto de Esaú (Gn 36:11, 15, 42; 1 Cr 1:36, 53). Famosa por su tradición sapiencial, es la patria de Elifaz el temanita (Job 2:11). Los oráculos proféticos anuncian juicio contra Temán como emblema de todo Edom (Jer 49:7, 20; Ez 25:13; Am 1:12; Abd 9). Habacuc 3:3 sitúa la aproximación teofánica de Dios «desde Temán», en paralelo con el monte Sinaí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145114, 'spa', 'Nombre propio judío', 'Figura de Judá conservada exclusivamente en registros genealógicos, cuyo nombre posiblemente refleja asociaciones geográficas meridionales (temani = sureño, o vinculado a Temán). Esta preservación genealógica era fundamental para el proyecto del Cronista de establecer la identidad comunitaria postexílica mediante la continuidad ancestral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145115, 'spa', 'Temanita (gentilicio)', 'El adjetivo gentilicio ha-Temani (הַתֵּימָנִי), que aparece siempre con artículo definido, identifica a alguien procedente de Temán en Edom. Seis de sus ocho apariciones se vinculan a Elifaz en Job (2:11; 4:1; 15:1; 22:1; 42:7, 9), haciéndolo prácticamente sinónimo de su identidad. Temán era famoso por su sabiduría (Jer 49:7), lo cual añade una profundidad irónica a los discursos de Elifaz, pues él representa la sagacidad edomita, aunque Dios finalmente lo reprende.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145119, 'spa', 'Gentilicio desconocido', 'Un gentilicio de origen desconocido que identifica a uno de los guerreros de élite de David. La oscuridad del término subraya cuántos topónimos locales y designaciones de clan se han perdido en la historia, conservados únicamente en estos breves registros militares que alguna vez tuvieron significado social para sus audiencias originales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145120, 'spa', 'Jugo de uva recién prensado o mosto, representando el rendimiento de la viña ant', 'Jugo de uva recién prensado o mosto, representando el rendimiento de la viña antes de la fermentación completa. Aparece característicamente en la tríada agrícola dagan-tirosh-yitshar (''grano, mosto y aceite'') como expresión abreviada de la prosperidad del pacto (Dt 7:13; 11:14; 14:23; 28:51; Os 2:10, 24; Jl 2:19). Se distingue de yayin (''vino fermentado'') en Miqueas 6:15 y Oseas 4:11, aunque la frontera entre ambos no siempre es nítida. Isaías 65:8 sitúa el tirosh todavía dentro del racimo, y Joel 2:24 visualiza los lagares rebosando de él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145138, 'spa', 'Nombre propio judío', 'Descendiente de Judá a través de Jehallelel, este nombre aparece en listas genealógicas con variantes textuales menores. Si está relacionado con la raíz ''temor'', ejemplificaría la práctica de dar a los hijos nombres que reflejan devoción religiosa o circunstancias del nacimiento, un patrón frecuente en la nomenclatura bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145140, 'spa', 'Macho cabrío', 'Designa al macho de la cabra como ganado valioso y símbolo de virilidad u orgullo. Los pasajes de Génesis vinculan a estos animales con la riqueza y el manejo reproductivo de los rebaños, mientras que Proverbios emplea al macho cabrío que se pavonea como emblema de un caminar seguro y señorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145141, 'spa', 'Opresión por los poderosos', 'Opresión o daño infligido por los poderosos. Salmo 10:7 lista la ''opresión'' entre el arsenal verbal del malvado (con maldición y engaño). Salmo 55:11 lamenta que la ''opresión'' nunca deja las calles de la ciudad—abuso endémico. Salmo 72:14 promete redención ''de la opresión y la violencia''—el rey justo terminará la explotación. Proverbios 29:13 contrasta al pobre con ''el opresor'' (hombre de opresiones)—Dios ve a ambos. Las glosas multilingües uniformemente traducen el sentido de abuso institucional y violencia estructural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145142, 'spa', 'Reunidos ante Dios', 'En la bendición de Moisés (Deuteronomio 33:3), describe la postura o posición de Israel en relación con Dios, ya sea reunido, conducido o sentado a sus pies para recibir instrucción. Las diversas traducciones interlingüísticas reflejan una dificultad textual genuina, y los traductores optan por imágenes de asamblea, sumisión o atención reverente acordes con el contexto de recibir la Torá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145144, 'spa', 'Morada divina fija', 'En Job 23:3 designa la morada fija o trono de Dios, el lugar establecido donde Job desea presentar su causa. El término implica permanencia y estabilidad: el lugar de Dios no es arbitrario sino establecido, en paralelo con otros vocablos para trono o morada divina (מָכוֹן). Las traducciones multilingües optan por ''morada'' o ''trono'', reconociendo el sentido de un lugar fijo y de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145146, 'spa', 'Explotación violenta', 'En Proverbios 29:13 describe la actividad característica del opresor: explotación violenta y agravio. Los glosarios multilingües apuntan consistentemente a la opresión, con el contexto contrastando al opresor con el pobre. El término pertenece a la ética social de la literatura sapiencial, que condena a quienes usan el poder para dañar en vez de proteger a los vulnerables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145147, 'spa', 'Perfección terrenal limitada', 'En el Salmo 119:96 representa el grado máximo de perfección o plenitud terrenal, que el salmista ha descubierto limitado. El contraste establece la naturaleza ilimitada de la palabra de Dios: mientras toda perfección creada tiene límites (un ''fin''), la instrucción divina es infinita. Los glosarios multilingües lo traducen consistentemente como ''perfección'', reconociendo el punto filosófico-teológico sobre la plenitud finita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145148, 'spa', 'Fin, límite extremo', 'El punto final espacial o conceptual, el confín más lejano de algo. Se usa del extremo de un edificio (Neh 3:21), la frontera entre luz y tinieblas (Job 26:10) y el límite insondable de Dios (Job 11:7). El español ''confín'' y ''fin'' reflejan un límite terminal. Job 28:3 extiende esto a los confines más remotos que un minero puede explorar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145149, 'spa', 'Azul (estambre/tela azul-violeta) — El tinte azul-violeta derivado del caracol m', 'Azul (estambre/tela azul-violeta) — El tinte azul-violeta derivado del caracol múrex y, por metonimia, el estambre, hilo o tela teñida con él. Predominantemente un término textil cultual, aparece en la tríada תְּכֵלֶת-אַרְגָּמָן-תוֹלַעַת שָׁנִי (azul-púrpura-escarlata) para las cortinas del tabernáculo, los velos y las vestiduras sacerdotales (Éx 25:4; 26:1, 31, 36; 28:5-33). También se usa para el cordón azul de la placa del turbante del sumo sacerdote (Éx 28:37; 39:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145155, 'spa', 'Ser recto, ser evaluado como justo — Nifal', 'Ser recto, ser evaluado como justo — Nifal: ser justo, recto o debidamente evaluado. Es el sentido más frecuente, con diez ocurrencias concentradas en Ezequiel 18 y 33. El estribillo repetido «el camino del Señor no es recto» (לֹא יִתָּכֵן, Ez 18:25, 29; 33:17, 20) usa la voz pasiva para expresar «medido conforme a una norma y hallado conforme». En 1 Samuel 2:3, Ana declara que «por él son pesadas las acciones».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145157, 'spa', 'Pesar, evaluar — Qal participio', 'Pesar, evaluar — Qal participio: pesar o evaluar corazones y espíritus. Tres ocurrencias en Proverbios (16:2; 21:2; 24:12) donde Dios es el sujeto que «pesa» las motivaciones internas del ser humano. Preserva la metáfora concreta de medición aplicada a realidades morales invisibles. Es la contraparte activa del sentido 1: Dios realiza la pesada y los humanos son medidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145158, 'spa', 'Medir, repartir — Piel', 'Medir, repartir — Piel: medir o distribuir cantidades físicas. Tres ocurrencias (Job 28:25; Is 40:12, 13) donde Dios mide las aguas, el viento y los cielos mismos. Es el sentido más concreto de la raíz, el más cercano a su núcleo etimológico de medición estandarizada. Presenta a Dios como el calibrador maestro que fija las dimensiones de la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145159, 'spa', 'Pesado (pasivo) — Pual pasivo', 'Pesado (pasivo) — Pual pasivo: pesado (referido a dinero). Una sola ocurrencia en 2 Reyes 12:11, donde la plata «que fue pesada» se entrega a los obreros del templo. Es un sentido comercial-transaccional: la moneda se verificaba por peso antes del pago, preservando el significado literal de medición en el contexto mundano de la contabilidad del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145161, 'spa', 'Establecer, afianzar — Piel', 'Establecer, afianzar — Piel: establecer firmemente o poner en orden. Una ocurrencia en el Salmo 75:3 («yo he sostenido sus columnas»), donde el significado se extiende más allá de la medición hacia el concepto de estabilizar o calibrar. El desarrollo semántico de «medir con precisión» a «poner en el orden debido» es natural: lo correctamente medido queda firmemente establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145165, 'spa', 'Ciudad simeonita', 'Ciudad simeonita preservada en los registros territoriales del Cronista, este topónimo no ha dejado otra huella en fuentes bíblicas o extrabíblicas. La conjunción indica que aparece en una serie de ciudades que marcan los asentamientos de Simeón, como parte del interés de Crónicas en documentar las reclamaciones territoriales tribales incluso cuando las ubicaciones físicas ya no eran claramente identificables en el período postexílico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145167, 'spa', 'Manto regio suntuoso', 'En Ester 8:15 describe el lujoso manto que Mardoqueo viste al salir de la presencia del rey con honores, confeccionado de lino fino y púrpura. La prenda forma parte de un atuendo regio completo que exhibe públicamente su nuevo estatus. La evidencia interlingüística muestra ''manto'' o ''vestidura'', reconociendo esta como una prenda exterior prestigiosa que señalaría rango a todos cuantos lo vieran en Susa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145168, 'spa', 'Montículo de ruinas', 'Montículo de escombros dejado tras la destrucción de una ciudad, que implica desolación permanente. Josué 8:28 y Deuteronomio 13:16 lo combinan con ''para siempre'' (עוֹלָם) para subrayar su carácter irreversible. Jeremías 49:2 añade ''desolación'' (שְׁמָמָה). En español se traduce comúnmente como ''montón'' o ''ruina'', mientras que el francés a veces deja el hebreo sin traducir, reflejando su naturaleza de término técnico arqueológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145171, 'spa', 'Penalidad prolongada', 'Alude a la carga acumulativa de una aflicción sostenida, no un dolor momentáneo sino la experiencia agotadora de una angustia prolongada. Abarca tanto las circunstancias externas adversas como su efecto interno debilitante. Moisés relata a Jetro las penalidades de Israel (Éx 18:8) y Nehemías confiesa las grandes tribulaciones sufridas por el pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145172, 'spa', 'Sequía intensa', 'En Oseas 13:5, describe las condiciones de aridez extrema del desierto donde Dios pastoreó a Israel durante el éxodo. El plural intensifica el significado: una sequía severa y mortal. La evidencia interlingüística confirma que se trata de vocabulario ambiental que retrata el desierto como un lugar de sequedad implacable que requería el sustento divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145174, 'spa', 'Vestidura metafórica', 'En Isaías 59:17, esta vestidura forma parte del atuendo de combate de Dios como guerrero divino. Se reviste de venganza como quien se pone indumentaria, preparándose para actuar en favor de su pueblo oprimido. La imagen influyó en textos posteriores como Efesios 6, estableciendo la tradición de la armadura espiritual en la literatura bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145175, 'spa', 'Nieve simbólica', 'En Daniel 7:9, proporciona el símil para las vestiduras del Anciano de Días: blancas ''como la nieve.'' La imagen transmite pureza absoluta y un brillo deslumbrante, una blancura radiante capaz de cegar los ojos humanos. En la imaginería antigua, como en la actual, la blancura de la nieve representaba el estándar máximo de pureza y esplendor divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145176, 'spa', 'Sentido activo dominante en Qal', 'Sentido activo dominante en Qal: colgar o suspender a alguien o algo, especialmente en contextos de ejecución o exhibición pública de cadáveres. Faraón cuelga al jefe de los panaderos (Gn 40:22); Josué cuelga al rey de Hai (Jos 8:29); Ester pide que los hijos de Amán sean colgados (Est 9:13-14). La forma imperativa aparece en Deuteronomio 21:22: ''lo colgaréis en un madero''. El español ''colgar'' y el francés ''pendre'' abarcan todo el registro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145177, 'spa', 'El tronco intensivo Piel', 'El tronco intensivo Piel: colgar o fijar mediante suspensión con énfasis en la completitud o deliberación. En Ezequiel 27:10-11, los guerreros cuelgan sus escudos y yelmos en los muros de Tiro como exhibición ornamental — un contexto militar-decorativo muy distinto de la ejecución judicial. La intensificación del Piel sugiere una colocación cuidadosa y deliberada. Solo dos apariciones, ambas en el lamento de Ezequiel sobre Tiro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145185, 'spa', 'El participio activo Qal usado como epíteto divino', 'El participio activo Qal usado como epíteto divino: ''el que cuelga'' — una sola aparición magnífica en Job 26:7 donde Dios es descrito como ''el que cuelga la tierra sobre la nada'' (toleh erets al-belimah). Aquí las asociaciones violentas y jurídicas del verbo desaparecen por completo, reemplazadas por un retrato cosmológico del poder creador divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145190, 'spa', 'El participio pasivo Qal que describe el estado de estar colgado o suspendido — ', 'El participio pasivo Qal que describe el estado de estar colgado o suspendido — una persona u objeto ya en suspensión. Deuteronomio 21:23 pronuncia la declaración teológicamente cargada ''el colgado es maldición de Dios'', que Pablo aplica después a la crucifixión de Cristo. En Cantares 4:4 mil escudos ''cuelgan'' de la torre de David, y en 2 Samuel 18:10 Absalón es visto ''colgado'' de la encina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145192, 'spa', 'El Nifal pasivo', 'El Nifal pasivo: ser colgado, describiendo al sujeto como sometido a ejecución por ahorcamiento. Bigtán y Teres ''fueron colgados'' después de que se descubriera su complot de asesinato (Est 2:23); los príncipes de Judá ''fueron colgados'' por sus manos en Lamentaciones 5:12. El español ''fueron colgados'' y el francés ''furent pendus'' emplean la voz pasiva para corresponder con la morfología hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145200, 'spa', 'Murmuración, queja', 'Sustantivo que denota murmuraciones, quejas formales o protestas dirigidas contra Dios o sus líderes designados. Las ocho apariciones nominales se centran en la rebelión de Israel en el desierto: en Éx 16:7-12 Dios oye las quejas sobre el maná y las codornices, mientras que Nm 14:27 y 17:20-25 emplean el término en conexión con la rebelión de Coré y sus consecuencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145204, 'spa', 'Murmurar (participio Hifil)', 'Forma participial del Hifil con función verbal, que significa ''los que murmuran'' o ''vosotros que murmuráis''. En Éx 16:8 esta forma aparece junto al sustantivo, creando un eco retórico incisivo: ''vuestras murmuraciones que murmuráis contra el SEÑOR''. El español ''murmuráis'' capta la fuerza verbal activa que la distingue del sustantivo estático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145205, 'spa', 'Ancestro efraimita', 'Un ancestro efraimita preservado en el marco genealógico de Crónicas, este nombre mantiene las conexiones de linaje dentro de los descendientes de José. La conjunción indica que aparece en una serie de engendraciones, como eslabón de la cadena genealógica que establece la identidad tribal y los derechos de herencia para la comunidad postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145207, 'spa', 'Recipiente de flechas', 'En Génesis 27:3, Isaac dice a Esaú que tome ''tu aljaba y tu arco,'' el equipo necesario para la expedición de caza que conduciría a la escena decisiva de la bendición. El término designa específicamente el contenedor de flechas, distinguiéndolo del arco mismo. La evidencia interlingüística muestra consistentemente ''aljaba'' o ''portaflechas,'' confirmando el vocabulario técnico de arquería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145208, 'spa', 'Ordinal: tercero', 'En Daniel 2:39, este ordinal identifica el tercer reino en la secuencia de imperios representados por los componentes de la estatua. Tras Babilonia (oro) y el segundo reino (plata), este reino de bronce representa la siguiente fase de la historia imperial. Las variantes Qere/Ketiv reflejan tradiciones de pronunciación preservadas por los escribas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145209, 'spa', 'Rango: tercer gobernante', 'En Daniel 5:7, describe el rango político que Belsasar promete a quien interprete la escritura misteriosa: será «tercero» en el reino. Esto probablemente significa tercer en mando o miembro de un triunvirato, una posición de poder considerable justo debajo del rey y el príncipe heredero, reflejando la estructura jerárquica de las cortes del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145210, 'spa', 'Ordinal: forma Ketiv', 'La forma escrita (Ketiv) de «tercero» en la secuencia de reinos de Daniel 2:39 identifica el reino de bronce que sigue a Babilonia y al segundo imperio. La coexistencia de las formas Ketiv y Qere muestra cómo los masoretas preservaron múltiples tradiciones textuales, permitiendo conocer tanto la escritura original como la pronunciación tradicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145211, 'spa', 'Elevado, excelso', 'En Ezequiel 17:22, este adjetivo intensifica la descripción del monte donde Dios plantará el cedro mesiánico: es tanto «alto» como «excelso», enfatizando doblemente su elevación. Las traducciones multilingües optan por «elevado», «excelso» o «alto», reflejando su carácter de adjetivo descriptivo que combina altura física y dignidad simbólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145212, 'spa', 'Surco agrícola', 'Surco trazado por el arado en un campo, la unidad básica del cultivo agrícola. Las cinco ocurrencias se relacionan con tierra labrada. Oseas 10:4 y 12:11 usan la expresión ''surcos del campo'' como imagen agrícola concreta. Job 31:38 personifica los surcos llorando, y el Salmo 65:10 describe a Dios asentando los surcos con la lluvia. En español se traduce uniformemente como ''surco(s)'', al igual que el francés ''sillon(s)''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145213, 'spa', 'Talmai (nombre propio)', 'Nombre propio que designa a dos individuos: (a) un gigante anaquita en Hebrón enfrentado durante la conquista (Num 13:22; Jos 15:14; Jue 1:10), y (b) el rey de Gesur, suegro de David por medio de su hija Maaca, y abuelo de Absalón, quien le dio refugio tras el asesinato de Amnón (2 Sam 3:3; 13:37; 1 Cr 3:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145215, 'spa', 'Estudiante, aprendiz', 'En 1 Crónicas 25:8, designa al estudiante o aprendiz de música que aprende de un maestro instructor. El sorteo para las asignaciones del servicio del templo empareja maestros con discípulos, mostrando una educación musical estructurada entre los levitas. Esto anticipa la prominencia posterior del término en el judaísmo rabínico, donde se convirtió en la palabra estándar para el discípulo de un rabino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145217, 'spa', 'Vestido de escarlata', 'En Nahúm 2:3, describe a los valientes de Nínive como «vestidos de escarlata», guerreros ataviados con prendas carmesí o portando escudos teñidos de rojo. La imagen transmite tanto esplendor militar como presagio sangriento: la vestimenta escarlata anticipa el derramamiento de sangre en la destrucción de la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145218, 'spa', 'Armería o hileras', 'En Cantar de los Cantares 4:4, describe la función o apariencia de la torre de David con la que se compara el cuello de la amada. Ya sea «armería», «hileras de escudos» o «trofeos», el término evoca fuerza militar y exhibición imponente. Las traducciones multilingües reflejan la dificultad interpretativa, reconociendo que el contexto de escudos colgados sugiere un uso militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145220, 'spa', 'tres (numeral arameo)', 'Numeral cardinal arameo «tres», que abarca las formas masculina y femenina así como construcciones pronominales («los tres»). Sus ocurrencias clave incluyen las especificaciones constructivas del templo reconstruido (Esd 6:4), los tres jóvenes en el horno de Nabucodonosor (Dn 3:23-24), las tres semanas de duelo de Daniel (Dn 10:2-3), las tres costillas en la boca de la bestia (Dn 7:5) y los tres presidentes del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145225, 'spa', 'Rizos ondulados', 'En Cantar de los Cantares 5:11, describe la cualidad o apariencia de los mechones del amado: ondulados, rizados o colgando en racimos como frondas de palmera. La imagen enfatiza un cabello abundante y lustroso, parte de la descripción física detallada del amante. La incertidumbre entre los intérpretes refleja la dificultad de precisar la metáfora botánica o visual exacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145226, 'spa', 'íntegro, recto, perfecto — Plenitud moral, intachabilidad e integridad delante d', 'íntegro, recto, perfecto — Plenitud moral, intachabilidad e integridad delante de Dios. Este es el sentido dominante, abarcando trece de las catorce apariciones. Job es llamado ''ish tam'' (Job 1:1, 1:8, 2:3), y el Salmo 37:37 exhorta al lector a ''considerar al íntegro''. En Cantar de los Cantares 5:2 y 6:9, la amada es ''mi perfecta'' (tammati), un uso que extiende la completitud de la ética a la belleza. El francés ''integre'' y el español ''íntegro'' capturan bien este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145230, 'spa', 'apacible, sencillo, tranquilo — De carácter tranquilo, sencillo y de inclinación', 'apacible, sencillo, tranquilo — De carácter tranquilo, sencillo y de inclinación doméstica; describe un temperamento más que un juicio moral. Se usa únicamente de Jacob en Génesis 25:27, donde ''ish tam'' contrasta con Esaú el cazador. El inglés lo traduce como ''quiet'' o ''plain'', el español como ''sencillo'' y el francés como ''tranquille''. Algunos eruditos lo consideran el mismo sentido raíz de ''completo'' aplicado al carácter, pero el contexto narrativo lo distingue claramente como un rasgo de temperamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145231, 'spa', 'Adverbio locativo', 'Adverbio deíctico sencillo que indica ubicación, empleado en la prosa administrativa de Esdras para referirse a sitios de archivo y depósitos del tesoro específicos dentro del reino persa. Su traducción uniforme en todas las lenguas (español «allí», francés «là») confirma su función como deíctico espacial sin matiz especial más allá de la simple localización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145232, 'spa', 'Rectitud moral e intachabilidad de carácter, el sentido dominante en 16 aparicio', 'Rectitud moral e intachabilidad de carácter, el sentido dominante en 16 apariciones. La frase clave ''betom levavi'' (en integridad de mi corazón) aparece en la defensa de Abimelec (Gn 20:5-6) y en el encargo de Dios a Salomón (1 R 9:4). Proverbios vincula repetidamente caminar ''en integridad'' (betom) con seguridad y justicia (Pr 10:9; 19:1; 20:7; 28:6). El español ''integridad'' y el alemán ''Lauterkeit'' captan la noción de pureza indivisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145234, 'spa', 'Inocencia o ingenuidad, actuar sin intención maliciosa ni conocimiento oculto', 'Inocencia o ingenuidad, actuar sin intención maliciosa ni conocimiento oculto. Los hombres que siguieron a Absalón iban ''en su inocencia'' (betummam), sin saber de sus planes traidores (2 S 15:11). Un soldado tensó su arco ''en su inocencia'' (letummo), sin apuntar deliberadamente, pero hirió al rey Acab (1 R 22:34; 2 Cr 18:33). El francés y el español lo traducen como ''dans leur innocence / en su inocencia''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145237, 'spa', 'Plenitud o completitud cuantitativa, que retorna a la raíz etimológica del verbo', 'Plenitud o completitud cuantitativa, que retorna a la raíz etimológica del verbo tamam (estar completo). Job 21:23 describe a quien muere ''en su plena prosperidad'', es decir, en el apogeo de su bienestar, mientras que Isaías 47:9 advierte que las calamidades vendrán ''en toda su plenitud''. El español ''plenitud'' intenta captar esta totalidad cuantitativa, no moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145239, 'spa', 'Completitud o terminación temporal, un uso raro donde el sustantivo funciona com', 'Completitud o terminación temporal, un uso raro donde el sustantivo funciona como infinitivo verbal que significa ''el completar/finalizar de''. Levítico 25:29 habla del periodo de redención que dura hasta ''el cumplimiento de'' un año completo. El español ''el fin de'' y el francés ''complétion de'' expresan este sentido temporal de un periodo que llega a su término señalado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145240, 'spa', 'Uso sustantivado para designar a una persona íntegra o intachable, funcionando c', 'Uso sustantivado para designar a una persona íntegra o intachable, funcionando como sustantivo de cualidad que representa a quien la encarna. Proverbios 10:29 dice que el camino del SEÑOR es fortaleza ''para el íntegro'' (lattom), y Proverbios 13:6 dice que la justicia guarda ''al de camino intachable'' (tam-darekh). El alemán ''untadelig'' (irreprochable) capta esta cualidad personal y sustantivada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145249, 'spa', 'Integridad moral', 'Integridad o entereza moral del carácter, especialmente mantenida bajo prueba. Se concentra en el prólogo y los diálogos de Job: Dios afirma la integridad de Job (2:3), su esposa la cuestiona (2:9), y Job la defiende con fiereza (27:5; 31:6). Tanto en inglés como en español y francés se traduce uniformemente como ''integridad''/''intégrité'', una convergencia poco frecuente que subraya la estabilidad semántica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145250, 'spa', 'Asombrarse, maravillarse', 'Quedar atónito, pasmado o sobrecogido por un asombro tan intenso que puede dejar sin habla o paralizado. En Gn 43:33 los hermanos se miran incrédulos; en Sal 48:5 los reyes enemigos ven Sion y retroceden estupefactos; en Job 26:11 las columnas del cielo ''se asombran'' ante la reprensión de Dios. El Hitpael en Hab 1:5 intensifica el imperativo Qal, produciendo un ''¡asombraos sobremanera!'' de fuerza redoblada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145258, 'spa', 'Maravillas divinas proclamadas', 'Maravillas o milagros divinos en proclamaciones reales. Daniel 4:2 y 4:3 lo usan en el decreto de Nabucodonosor: ''las señales y maravillas que el Dios Altísimo ha hecho conmigo''—específicamente su humillación y restauración. Daniel 6:27 lo incluye en la proclamación de Darío tras la liberación de Daniel: Dios ''hace señales y maravillas en el cielo y la tierra.'' El emparejamiento con ''señales'' (ath) es formulaico. Las glosas multilingües reflejan consistentemente el lenguaje de asombro sobrenatural y reconocimiento divino por parte de gobernantes gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145260, 'spa', 'Deidad Tamuz', 'En Ezequiel 8:14, esta deidad babilónica es objeto del llanto ritual de las mujeres en el templo de Jerusalén, parte de la visión profética de abominaciones que profanan el santuario. El culto de Tamuz incluía ritos de duelo por la muerte del dios y su descenso al inframundo, prácticas que se habían infiltrado en el culto israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145261, 'spa', 'El adverbio ''ayer'' usado tanto en sentido literal como idiomático en la pareja t', 'El adverbio ''ayer'' usado tanto en sentido literal como idiomático en la pareja temol shilshom (''ayer y anteayer'') para significar ''anteriormente, en el pasado''. Pasajes clave: Gn 31:2, 5 (el cambio de actitud de Labán); Éx 4:10 (la protesta de Moisés de no ser elocuente ''ni de ayer ni de anteayer''). El español ''ayer'', el francés ''hier'' y el alemán ''gestern'' preservan el anclaje temporal concreto incluso donde el sentido es figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145264, 'spa', 'Forma, figura visible', 'La forma visible, figura o apariencia exterior de algo percibido — el contorno tal como se ve o podría verse. Central en la legislación teofánica y anti-idolátrica: Moisés contempla la ''forma del SEÑOR'' (Nm 12:8), Israel oyó una voz pero no vio forma alguna en Horeb (Dt 4:12, 15), y ninguna imagen tallada en forma alguna debe hacerse (Dt 4:16, 23, 25). Job 4:16 extiende esto a una aparición nocturna.');